// Minimal host test harness: no dependency, no framework, one exit code.
//
// A test file defines main() as `main_impl()` and includes this; the runner below is
// generated by the TEST_MAIN macro so each file is its own executable and ctest can
// report it separately.
#pragma once

#include <cstdio>

static int g_checks = 0;
static int g_failures = 0;

static void check_impl(bool ok, const char *expr, const char *file, int line)
{
    ++g_checks;
    if (!ok) {
        ++g_failures;
        std::printf("FAIL %s:%d  %s\n", file, line, expr);
    }
}

static int check_result(const char *suite)
{
    if (g_failures == 0) {
        std::printf("ok   %s (%d checks)\n", suite, g_checks);
        return 0;
    }
    std::printf("FAIL %s: %d of %d checks failed\n", suite, g_failures, g_checks);
    return 1;
}

#define CHECK(cond) check_impl((cond), #cond, __FILE__, __LINE__)
#define CHECK_EQ(a, b) check_impl((a) == (b), #a " == " #b, __FILE__, __LINE__)
#define TEST_MAIN(fn, name) int main() { fn(); return check_result(name); }
